// Build the request exactly as src/providers.py does, so the workflow and the CLI
// hit the same API contract. Gemini's responseSchema is an OpenAPI subset and rejects
// additionalProperties, so it is stripped here just as it is there.
const merged = Object.assign({}, ...$input.all().map(i => i.json));
const { system, schema, ...facts } = merged;

function strip(node) {
  if (node === null || typeof node !== 'object') return node;
  if (Array.isArray(node)) return node.map(strip);
  const out = {};
  for (const [k, v] of Object.entries(node)) {
    if (k === 'additionalProperties') continue;
    out[k] = strip(v);
  }
  return out;
}

return [{
  json: {
    system_instruction: { parts: [{ text: system }] },
    contents: [{
      role: 'user',
      parts: [{
        text: "Here is the fact pack for this month's review. Write the briefing.\n\n"
              + '```json\n' + JSON.stringify(facts, null, 2) + '\n```',
      }],
    }],
    generationConfig: {
      responseMimeType: 'application/json',
      responseSchema: strip(schema),
    },
  },
}];

// The model returns prose only — no numbers. This assembles the markdown the same
// way src/render.py:compose_briefing does: prose from the model, tables from the facts.
const prose = JSON.parse($json.candidates[0].content.parts.map(p => p.text || '').join(''));
const facts = $('Get fact pack').first().json;

const usd = v => '$' + Math.round(v).toLocaleString('en-US');
const k = v => (Math.abs(v / 1000) >= 100)
  ? '$' + Math.round(v / 1000).toLocaleString('en-US') + 'k'
  : '$' + (v / 1000).toFixed(1) + 'k';
const pct = v => (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
const n = v => v.toLocaleString('en-US');
const rat = Object.fromEntries(prose.reorder_rationales.map(r => [r.sku, r.rationale]));

const L = [`# S&OP Briefing — ${facts.meta.reporting_month}`, '', prose.opening_line, ''];
L.push('## The decision this month', '',
  `**${prose.headline.sku}.** ${prose.headline.reasoning}`, '', prose.headline.decision, '');
if (prose.capital_note) L.push(prose.capital_note, '');

L.push('## What to order, in priority order', '',
  'Ranked by revenue at stake rather than by who runs out first.', '',
  '| # | SKU | Order | By | Cover now | Revenue at stake |', '|---|---|---|---|---|---|');
for (const r of facts.reorder_queue) {
  const by = r.is_overdue ? '**Overdue**' : r.order_by_date;
  L.push(`| ${r.rank} | ${r.sku} | ${n(r.quantity_units)} units | ${by} | `
    + `${r.current_cover_months} of ${r.target_months_cover} months | `
    + `${usd(r.revenue_opportunity_usd)} |`);
}
L.push('');
for (const r of facts.reorder_queue) L.push(`- **${r.sku}** — ${rat[r.sku]}`, '');

L.push(`## How ${facts.meta.reporting_month} went`, '', prose.performance_note, '');
const bm = facts.portfolio.units_by_month, months = Object.keys(bm);
L.push('| ' + months.join(' | ') + ' | Period |', '|' + '---|'.repeat(months.length + 1),
  '| ' + months.map(m => n(bm[m])).join(' | ') + ` | ${pct(facts.portfolio.period_growth_pct)} |`, '');

if (prose.tension_notes.length) {
  L.push('## Also worth a decision', '');
  for (const t of prose.tension_notes) L.push(`- **${t.sku}** — ${t.note}`);
  L.push('');
}
if (prose.noise_note) L.push('## Not worth your attention', '', prose.noise_note, '');
if (prose.closing_action) L.push('## Before the next review', '', prose.closing_action, '');

L.push('---', '', '## Every SKU', '',
  '| SKU | Units | MoM | Trend/mo | Cover | Target | Opportunity |', '|---|---|---|---|---|---|---|');
const sorted = [...facts.skus].sort((a, b) => b.money.revenue_opportunity_usd - a.money.revenue_opportunity_usd);
for (const s of sorted) {
  L.push(`| ${s.sku} | ${n(s.demand.current_month_units)} | ${pct(s.trend.month_on_month_pct)} | `
    + `${pct(s.trend.monthly_growth_pct)} | ${s.inventory.current_cover_months} | `
    + `${s.inventory.target_months_cover} | ${usd(s.money.revenue_opportunity_usd)} |`);
}

return [{ json: { briefing: L.join('\n') + '\n', words: L.join(' ').split(/\s+/).length } }];
